import "strings"

func CalculateDiscount(itemsCount int, promoCode string, isVIP bool) float64 {
	// Граничные проверки
	if itemsCount <= 0 {
		return 0.0
	}

	discount := 0.0
	if isVIP {
		discount += 15.0
	}

	// Проверка промокода
	cleanPromo := strings.ToUpper(strings.TrimSpace(promoCode))
	if cleanPromo == "SALE2026" {
		discount += 20.0
	}

	if itemsCount >= 10 {
		discount += 5.0
	}

	if discount > 50.0 {
