import (
	"math/rand"
	"slices"
	"testing"
)

func CustomQuickSort(arr []int) {
	if len(arr) <= 1 {
		return
	}
	pivot := arr[len(arr)/2]
	left, right := 0, len(arr)-1

	for left <= right {
		for arr[left] < pivot {
			left++
		}
		for arr[right] > pivot {
			right--
		}
		if left <= right {
			arr[left], arr[right] = arr[right], arr[left]
			left++
			right--
		}
	}

	if right > 0 {
		CustomQuickSort(arr[:right+1])
	}
	if left < len(arr) {
		CustomQuickSort(arr[left:])
	}
}

func BenchmarkSortAlgorithmsComparison(b *testing.B) {
	const n = 10000
	template := make([]int, n)
	for i := range template {
		template[i] = rand.Intn(1000000)
	}

	work := make([]int, n)

	b.Run("Custom_QuickSort", func(b *testing.B) {
		b.ReportAllocs()
		for i := 0; i < b.N; i++ {
			b.StopTimer()
			copy(work, template)
			b.StartTimer()

			CustomQuickSort(work)
		}
	})

	b.Run("Standard_Slices_Sort", func(b *testing.B) {
		b.ReportAllocs()
		for i := 0; i < b.N; i++ {
			b.StopTimer()
			copy(work, template)
			b.StartTimer()

			slices.Sort(work)
		}
	})
}

